def fetch_air_quality(session, city, api_key, scale="us"):
    """Return the air quality index for a city."""
    params = {"q": city, "scale": scale, "appid": api_key}
    resp = session.get("https://api.weather.example/v2/air", params=params, timeout=5)
    resp.raise_for_status()
    pollution = resp.json().get("pollution", {})
    return pollution.get("aqi")

def fetch_incident_count(url):
    """Return the number of open incidents on a status page."""
    resp = requests.get(url + "/api/v2/incidents/unresolved.json", timeout=10)
    resp.raise_for_status()
    return len(resp.json()["incidents"])

def post_metric(session, base_url, name, value):
    """Report a numeric metric and return the id the server gave it."""
    body = {"name": name, "value": value}
    resp = session.post(base_url + "/metrics", json=body, timeout=10)
    resp.raise_for_status()
    return resp.json()["id"]

def submit_ticket(session, base_url, customer, subject, priority=None):
    """File a support ticket as a form post and return its number."""
    form = {"customer": customer, "subject": subject}
    if priority is not None:
        form["priority"] = priority
    resp = session.post(f"{base_url}/tickets", data=form, timeout=10)
    resp.raise_for_status()
    return resp.json()["number"]

def try_get_json(endpoint, query=None):
    """Return the JSON at an endpoint or None if the call fails."""
    try:
        reply = requests.get(endpoint, params=query, timeout=10)
        reply.raise_for_status()
        return reply.json()
    except requests.HTTPError as err:
        log.warning("GET %s -> %s", endpoint, err.response.status_code)
    except requests.Timeout:
        log.warning("GET %s timed out", endpoint)
    return None

def call_with_retries(fn, tries=5, initial_wait=1.0, retry_on=(OSError,)):
    """Run fn, retrying on failure and doubling the wait each time."""
    error = None
    for n in range(tries):
        try:
            return fn()
        except retry_on as exc:
            error = exc
            pause = initial_wait * (2 ** n)
            time.sleep(pause)
    raise error

def send_with_retry(session, verb, url, bad_codes=(500, 502, 504), max_tries=3, **kwargs):
    """Send a request again while the server keeps answering with a bad code."""
    resp = None
    for delay in backoff_delays(count=max_tries):
        resp = session.request(verb, url, timeout=15, **kwargs)
        if resp.status_code not in bad_codes:
            break
        time.sleep(delay)
    return resp

def poll_until_ready(check, limit=60.0, pause=2.0):
    """Call check repeatedly until it is truthy or the limit expires."""
    end_time = time.monotonic() + limit
    while time.monotonic() < end_time:
        result = check()
        if result:
            return result
        time.sleep(pause)
    return None

def linear_delays(step=1.0, count=5, ceiling=10.0):
    """Yield linearly growing delays up to a ceiling."""
    delay = step
    for _ in range(count):
        yield min(delay, ceiling)
        delay += step

def collect_events(session, url, batch=100):
    """Walk an endpoint that returns a next_cursor token until it runs out."""
    events = []
    token = None
    while True:
        query = {"limit": batch}
        if token:
            query["cursor"] = token
        resp = session.get(url, params=query, timeout=10)
        resp.raise_for_status()
        payload = resp.json()
        events.extend(payload["data"])
        token = payload.get("next_cursor")
        if not token:
            return events

def read_settings_file(path, fallback=None):
    """Load a JSON settings file; return fallback if the file is missing."""
    if not os.path.exists(path):
        return fallback
    with open(path, "r", encoding="utf-8") as fh:
        return json.load(fh)

def read_table(path, sep=";"):
    """Read a delimited file into a list of row dicts."""
    with open(path, newline="", encoding="utf-8") as fh:
        return list(csv.DictReader(fh, delimiter=sep))

def read_event_log(path):
    """Read a JSON-lines log into a list of dicts, skipping blank lines."""
    events = []
    with open(path, encoding="utf-8") as fh:
        for raw in fh:
            raw = raw.strip()
            if raw:
                events.append(json.loads(raw))
    return events

def read_cached_blob(folder, name, max_age=900):
    """Return the stored JSON for name unless it is older than max_age seconds."""
    path = os.path.join(folder, name[:2], name + ".json")
    try:
        age = time.time() - os.path.getmtime(path)
    except OSError:
        return None
    if age > max_age:
        return None
    with open(path, encoding="utf-8") as fh:
        return json.load(fh)

def drop_stale_entries(store, lifetime):
    """Remove entries older than lifetime seconds from a dict of (timestamp, value)."""
    now = time.time()
    old = [k for k, (made_at, _) in store.items() if now - made_at > lifetime]
    for key in old:
        del store[key]
    return len(old)

def sha1_of_file(path, block=1 << 16):
    """Hex SHA-1 digest of a file, read block by block."""
    h = hashlib.sha1()
    with open(path, "rb") as fh:
        for chunk in iter(lambda: fh.read(block), b""):
            h.update(chunk)
    return h.hexdigest()

def make_handle(display_name):
    """Turn a display name into a lowercase ASCII handle with dashes."""
    text = unicodedata.normalize("NFKD", display_name).encode("ascii", "ignore").decode("ascii")
    text = re.sub(r"[^\w\s-]", "", text).strip().lower()
    return re.sub(r"[-\s]+", "-", text)

def safe_upload_name(filename, limit=64):
    """Sanitise an upload name: slug the base name, keep a lowercase extension."""
    base, dot, suffix = filename.rpartition(".")
    if not dot:
        base, suffix = filename, ""
    cleaned = make_handle(base)[:limit] or "file"
    return cleaned + ("." + suffix.lower() if suffix else "")

def to_kebab(name):
    """Convert CamelCase identifiers to kebab-case."""
    first = re.sub(r"(.)([A-Z][a-z]+)", r"\1-\2", name)
    return re.sub(r"([a-z0-9])([A-Z])", r"\1-\2", first).lower()

def strip_markdown_links(md):
    """Replace [text](url) links by their text and tidy the spacing."""
    text = re.sub(r"\[([^\]]+)\]\([^)]*\)", r"\1", md)
    text = text.replace("**", "").replace("__", "")
    return re.sub(r"\s+", " ", text).strip()

def group_by_quarter(items, key="created"):
    """Group records into a dict keyed by 'YYYY-Qn'."""
    groups = defaultdict(list)
    for item in items:
        stamp = item[key]
        groups["%d-Q%d" % (stamp.year, (stamp.month - 1) // 3 + 1)].append(item)
    return dict(sorted(groups.items()))

def count_by_hour(timestamps):
    """Count how many timestamps fall in each clock hour."""
    counts = {}
    for stamp in timestamps:
        key = stamp.strftime("%Y-%m-%d %H:00")
        counts[key] = counts.get(key, 0) + 1
    return counts

@classmethod
