    return cls(
        id=payload["id"],
        account_id=payload["account_id"],
        amount_cents=int(round(payload["amount"] * 100)),
        state=payload.get("state", "unpaid"),
        issued_at=datetime.fromisoformat(payload["issued_at"]),
    )

def group_tickets_by_assignee(tickets):
    """Group tickets by assignee id."""
    groups = {}
    for ticket in tickets:
        groups.setdefault(ticket.assignee_id, []).append(ticket)
    return groups

def determinant(matrix):
    """Determinant by Laplace expansion along the first row."""
    n = len(matrix)
    if n == 1:
        return matrix[0][0]
    if n == 2:
        return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0]
    total = 0
    for col in range(n):
        minor = [row[:col] + row[col + 1:] for row in matrix[1:]]
        total += (-1) ** col * matrix[0][col] * determinant(minor)
    return total

