def solve_queens(n, row=0, cols=(), diag1=(), diag2=()):
    """Count the placements of n non-attacking queens."""
    if row == n:
        return 1
    count = 0
    for col in range(n):
        if col in cols or row - col in diag1 or row + col in diag2:
            continue
        count += solve_queens(n, row + 1, cols + (col,), diag1 + (row - col,), diag2 + (row + col,))
    return count

def to_roman(number):
    """Convert 1..3999 to a Roman numeral."""
    numerals = [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"), (90, "XC"),
                (50, "L"), (40, "XL"), (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")]
    out = []
    for value, symbol in numerals:
        while number >= value:
            out.append(symbol)
            number -= value
    return "".join(out)

def bst_insert(root, key):
    """Insert key into a binary search tree and return the new root."""
    if root is None:
        return Node(key)
    if key < root.key:
        root.left = bst_insert(root.left, key)
    else:
        root.right = bst_insert(root.right, key)
    return root

def primes_below(limit):
    """Sieve of Eratosthenes."""
    sieve = bytearray([1]) * limit
    sieve[:2] = b"\x00\x00"
    for i in range(2, int(limit ** 0.5) + 1):
        if sieve[i]:
            sieve[i * i::i] = bytearray(len(range(i * i, limit, i)))
    return [i for i, flag in enumerate(sieve) if flag]

def levenshtein(a, b):
    """Edit distance between two strings, two-row dynamic programming."""
    previous = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        current = [i]
        for j, cb in enumerate(b, 1):
            current.append(min(previous[j] + 1, current[j - 1] + 1, previous[j - 1] + (ca != cb)))
        previous = current
    return previous[-1]
